def _read_state(self, state: str, *, timeout: float = 5.0) -> bool:
    result = self._session._run_web_value(
        f"web.{state}", self.id, timeout_ms=_timeout_to_ms(timeout, 5.0),
    )
    return bool(result["value"])

def is_checked(self) -> bool:
    return self._read_state("is_checked")

def is_enabled(self) -> bool:
    return self._read_state("is_enabled")

def _run_web_value(
    self,
    method: str,
    element_id: str,
    **params: Any,
) -> dict[str, Any]:
    self._ensure_open()
    return self._client._run_web_value(
        method,
        element_id,
        **self._web_target_params(),
        **params,
    )

def _run_web_value(
    self,
    method: str,
    element_id: str,
    **params: Any,
) -> dict[str, Any]:
    self._ensure_method_supported(method)
    rpc_params = {
        "element_id": element_id,
        **params,
    }
    if "timeout_ms" in rpc_params:
        rpc_params["timeout_ms"] = int(rpc_params["timeout_ms"])
    result = self._rpc(method, rpc_params)
