def _resolve_web_ctx(self, params: dict[str, Any]) -> tuple[dict[str, Any] | None, dict[str, Any] | None]:
    if params.get("locator_kind") == "runtime_ref":
        return self.web_live_elements.resolve(str(params.get("element_id") or ""))
    ctx, err = self._resolve_ctx(params)
    if err is not None:
        return None, err
    assert ctx is not None
    if ctx.get("kind") != "web":
        return None, business_error(5, "unsupported_method")
    return ctx, None

